use std::fmt::Write as _;

use super::registry::Registry;
use super::value::{Kind, Value};

/// The page's frontmatter and introduction. The docs site renders the title, so the
/// page has no heading of its own.
const PAGE_HEAD: &str = "\
---
title: Settings
description: Every runtime setting, with its type, default and environment variable.
---

<!-- Do not edit: change the settings registry and regenerate this page. -->

This page is generated by `neon settings docs` from the server's settings registry.

Runtime settings apply without a restart. Each takes its value from the first of these
that has one:

1. its environment variable: `NEON_SETTINGS__` and the key in capitals, with `__` between
   levels, so `instance.name` is `NEON_SETTINGS__INSTANCE__NAME`
2. its key under `settings:` in the config file, `neon.yaml` or the file `NEON_CONFIG` names,
   one level per dot
3. the value saved in the database from the admin page
4. its default

A setting set by its environment variable or in the config file is pinned: the admin page
shows it but cannot change it.

| Key | Type | Default | Environment variable | Description |
|---|---|---|---|---|
";

impl Registry {
    /// The settings reference as a docs site page: frontmatter, an introduction, then
    /// one table row per setting in key order, so the same registry always gives the
    /// same page.
    pub fn reference_markdown(&self) -> String {
        let mut out = String::from(PAGE_HEAD);

        for def in self.definitions() {
            // Writing to a String cannot fail.
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | `{}` | {} |",
                def.key(),
                kind_label(def.kind()),
                default_label(def.default_value()),
                def.env_var(),
                escape(def.description()),
            );
        }

        out
    }
}

fn kind_label(kind: Kind) -> String {
    match kind {
        Kind::Enum(options) => format!("enum: {}", options.join(", ")),
        other => other.to_string(),
    }
}

fn default_label(value: &Value) -> String {
    match value {
        Value::Secret(_) => "empty".to_owned(),
        Value::String(s) if s.is_empty() => "empty".to_owned(),
        other => format!("`{}`", escape(&other.to_string())),
    }
}

/// Keeps a value inside its table cell.
fn escape(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use crate::settings::{Definition, Key};

    use super::*;

    #[test]
    fn rows_list_key_type_default_env_and_description() {
        let registry = Registry::builder()
            .define(Definition::string(
                Key::new("instance.name"),
                "Neon Workspace",
                "The name | shown.",
            ))
            .define(Definition::enumeration(
                Key::new("auth.registration"),
                &["open", "invite", "closed"],
                "invite",
                "Who may sign up.",
            ))
            .define(Definition::duration(
                Key::new("auth.session_idle"),
                Duration::from_secs(7 * 24 * 3600),
                "Idle sign-out.",
            ))
            .define(Definition::secret(
                Key::new("mail.password"),
                "The password.",
            ))
            .build()
            .expect("valid registry");

        let markdown = registry.reference_markdown();
        let rows: Vec<&str> = markdown.lines().filter(|l| l.starts_with("| `")).collect();

        assert!(markdown.ends_with(&format!("{}\n", rows[rows.len() - 1])));

        assert_eq!(
            rows,
            [
                "| `auth.registration` | enum: open, invite, closed | `invite` | `NEON_SETTINGS__AUTH__REGISTRATION` | Who may sign up. |",
                "| `auth.session_idle` | duration | `7d` | `NEON_SETTINGS__AUTH__SESSION_IDLE` | Idle sign-out. |",
                "| `instance.name` | string | `Neon Workspace` | `NEON_SETTINGS__INSTANCE__NAME` | The name \\| shown. |",
                "| `mail.password` | secret | empty | `NEON_SETTINGS__MAIL__PASSWORD` | The password. |",
            ]
        );
    }

    #[test]
    fn the_page_has_frontmatter_and_no_heading_of_its_own() {
        let registry = Registry::builder().build().expect("valid registry");

        let markdown = registry.reference_markdown();

        assert!(
            markdown.starts_with(
                "---\ntitle: Settings\ndescription: Every runtime setting, with its type, \
                 default and environment variable.\n---\n\n"
            ),
            "{markdown}"
        );
        assert!(!markdown.lines().any(|line| line.starts_with("# ")));
        assert!(markdown.contains("generated by `neon settings docs`"));
        assert!(markdown.ends_with("|---|---|---|---|---|\n"));
    }
}
